import numpy as np

def kmeans_step(X, centres):
    # assign each row to its nearest centre (ties: lower index),
    # then move each centre to the mean of its rows;
    # a centre with no rows stays where it was
    # return (labels, new_centres) as NumPy arrays
    X = np.asarray(X, float)
    C = np.asarray(centres, float)
    d = ((X[:, None, :] - C[None, :, :]) ** 2).sum(axis=2)
    labels = d.argmin(axis=1)
    new = C.copy()
    for j in range(len(C)):
        if (labels == j).any():
            new[j] = X[labels == j].mean(axis=0)
    return labels, new

def inertia(X, labels, centres):
    # sum of squared distances from each row to its own centre
    X = np.asarray(X, float)
    C = np.asarray(centres, float)
    return float(((X - C[np.asarray(labels)]) ** 2).sum())
